  switch (status) {
    case "Active":
      this.display(["active_status"]);
      break;
    case "Inactive":
      this.display(["inactive_status"]);
      break;
    case "Suspended":
      this.display(["suspended_status"]);
      break;
    case "Prospect":
      this.display(["prospect_status"]);
      break;
    case "Pending":
      this.display(["pending_status"]);
      break;
    default:
      break;
  }
};

const checkAccIntegrationType = async (organizationId) => {
  if (organizationId) {
    const resAI = await db
      .collection("accounting_integration")
      .where({ organization_id: organizationId })
      .get();

    if (resAI && resAI.data.length > 0) {
      const aiData = resAI.data[0];

      this.setData({ acc_integration_type: aiData.acc_integration_type });

      if (aiData.acc_integration_type === "No Accounting Integration") {
        this.disabled(
          [
            "supplier_type",
            "supplier_irbm_id",
            "supplier_area_id",
            "supplier_agent_id",
            "currency_id",
            "supplier_payment_term_id",
          ],
          false,
        );
      }
    }
  }
};

(async () => {
  try {
    const status = await this.getValue("supplier_status");

    let pageStatus = "";

    if (this.isAdd) pageStatus = "Add";
    else if (this.isEdit) pageStatus = "Edit";
    else if (this.isView) pageStatus = "View";
    else if (this.isCopy) pageStatus = "Clone";
    else throw new Error("Invalid page state");

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ organization_id: organizationId, page_status: pageStatus });

    switch (pageStatus) {
      case "Add":
        this.display(["active_status"]);
        await checkAccIntegrationType(organizationId);
        break;

      case "Edit":
        this.disabled(
          [
            "supplier_type",
            "supplier_com_name",
            "supplier_irbm_id",
            "supplier_code",
            "supplier_area_id",
            "supplier_agent_id",
            "currency_id",
            "supplier_payment_term_id",
            "supplier_credit_limit",
            "supplier_exceed_limit",
          ],
          true,
        );

        await showStatusHTML(status);
        await checkAccIntegrationType(organizationId);
        break;

      case "Clone":
        this.display(["active_status"]);
        await setPrefix(organizationId);
        break;

      case "View":
        this.hide(["button_cancel", "button_save"]);
        showStatusHTML(status);

        break;
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible("supplier_code_type", true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("supplier_code");
  const { options } = params;

  const optionsData = this.getOptionData("supplier_code_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("supplier_code_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        supplier_code_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ supplier_code_type: defaultData.value });
    }
  }
}, 200);

