// SUPPLIER_SAVE — the server-side save; see Supplier/SupplierSaveWorkflow.json.
const SUPPLIER_SAVE_WORKFLOW_ID = "2099333410365689858";

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
    this.hideLoading();
  }
};

const findFieldMessage = (obj) => {
  // Base case: if current object has the structure we want
  if (obj && typeof obj === "object") {
    if (obj.field && obj.message) {
      return obj.message;
    }

    // Check array elements
    if (Array.isArray(obj)) {
      for (const item of obj) {
        const found = findFieldMessage(item);
        if (found) return found;
      }
    }

    // Check all object properties
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const found = findFieldMessage(obj[key]);
        if (found) return found;
      }
    }
  }
  return null;
};

(async () => {
  try {
    this.showLoading();

    const data = this.getValues();

    await this.runWorkflow(
      SUPPLIER_SAVE_WORKFLOW_ID,
      { allData: data },
      () => {
        this.$message.success(
          `${data.page_status === "Edit" ? "Update" : "Add"} successfully`,
        );
        closeDialog();
      },
      (error) => {
        this.hideLoading();
        console.error(error);
        this.$message.error(
          error?.data?.msg || "An error occurred while saving the supplier.",
        );
      },
    );
  } catch (error) {
    this.hideLoading();

    let errorMessage = "";

    if (error && typeof error === "object") {
      errorMessage = findFieldMessage(error) || "An error occurred";
    } else {
      errorMessage = error;
    }

    this.$message.error(errorMessage);
    console.error(errorMessage);
  }
})();

